import{_ as s,c as a,a2 as i,o as n}from"./chunks/framework.CO0qOYmW.js";const u=JSON.parse('{"title":"1.1 认识 Linux","description":"","frontmatter":{"title":"1.1 认识 Linux","category":"运维 · Linux","tags":["Linux"],"excerpt":"Linux 严格来说只是一个内核（Kernel），由 Linus Torvalds 在 1991 年作为个人项目发布。它负责管理硬件资源（CPU、内存、磁盘、网络），并为上层应用程序提供统一的接口。 我们日常所说的\\"Linux 系统\\"，准确..."},"headers":[],"relativePath":"operation/00-linux/01-intro.md","filePath":"operation/00-linux/01-intro.md","lastUpdated":1773591891000}'),d={name:"operation/00-linux/01-intro.md"};function e(l,t,r,p,o,h){return n(),a("div",null,t[0]||(t[0]=[i(`<h1 id="_1-1-认识-linux" tabindex="-1">1.1 认识 Linux <a class="header-anchor" href="#_1-1-认识-linux" aria-label="Permalink to &quot;1.1 认识 Linux&quot;">​</a></h1><h2 id="linux-是什么" tabindex="-1">Linux 是什么？ <a class="header-anchor" href="#linux-是什么" aria-label="Permalink to &quot;Linux 是什么？&quot;">​</a></h2><p>Linux 严格来说只是一个<strong>内核（Kernel）</strong>，由 Linus Torvalds 在 1991 年作为个人项目发布。它负责管理硬件资源（CPU、内存、磁盘、网络），并为上层应用程序提供统一的接口。</p><p>我们日常所说的&quot;Linux 系统&quot;，准确的叫法是 <strong>GNU/Linux</strong>，是 Linux 内核 + GNU 工具集（ls、grep、bash 等）+ 其他软件的组合。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│           用户应用程序               │  ← 你写的代码、nginx、mysql...</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│         Shell / 命令行工具           │  ← bash、zsh、ls、grep...</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│         系统调用接口 (syscall)        │  ← 程序与内核沟通的桥梁</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│           Linux 内核                 │  ← 进程调度、内存管理、驱动...</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│             硬件                     │  ← CPU、内存、磁盘、网卡...</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="linux-发行版" tabindex="-1">Linux 发行版 <a class="header-anchor" href="#linux-发行版" aria-label="Permalink to &quot;Linux 发行版&quot;">​</a></h2><p>发行版（Distribution，简称 Distro）= Linux 内核 + 一套预装软件 + 包管理器 + 配置工具的整体打包。</p><p>主流发行版及其特点：</p><table tabindex="0"><thead><tr><th>发行版</th><th>包管理器</th><th>适用场景</th><th>代表版本</th></tr></thead><tbody><tr><td><strong>Ubuntu</strong></td><td>APT (<code>.deb</code>)</td><td>新手友好，桌面 &amp; 服务器</td><td>22.04 LTS</td></tr><tr><td><strong>Debian</strong></td><td>APT (<code>.deb</code>)</td><td>稳定优先，生产服务器</td><td>Debian 12</td></tr><tr><td><strong>CentOS Stream</strong></td><td>DNF (<code>.rpm</code>)</td><td>企业环境，RedHat 兼容</td><td>Stream 9</td></tr><tr><td><strong>Rocky Linux</strong></td><td>DNF (<code>.rpm</code>)</td><td>CentOS 替代，企业级稳定</td><td>Rocky 9</td></tr><tr><td><strong>Arch Linux</strong></td><td>Pacman</td><td>高度可定制，进阶用户</td><td>滚动更新</td></tr><tr><td><strong>Alpine Linux</strong></td><td>APK</td><td>极简主义，Docker 镜像常用</td><td>3.x</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">初学者推荐</p><p><strong>Ubuntu 22.04 LTS</strong> 是最好的入门选择：</p><ul><li>社区庞大，遇到问题容易搜到解决方案</li><li>文档和教程最多</li><li>LTS（长期支持版）稳定可靠，5 年官方维护</li></ul></div><hr><h2 id="linux-的核心设计哲学" tabindex="-1">Linux 的核心设计哲学 <a class="header-anchor" href="#linux-的核心设计哲学" aria-label="Permalink to &quot;Linux 的核心设计哲学&quot;">​</a></h2><p>理解这几个原则，能帮你更快建立对 Linux 的直觉：</p><h3 id="_1-一切皆文件" tabindex="-1">1. 一切皆文件 <a class="header-anchor" href="#_1-一切皆文件" aria-label="Permalink to &quot;1. 一切皆文件&quot;">​</a></h3><p>Linux 中几乎所有东西都被抽象为文件：</p><ul><li>普通文档 → 文件</li><li>硬盘、U盘 → <code>/dev/sda</code>、<code>/dev/sdb</code></li><li>键盘、鼠标 → <code>/dev/input/</code></li><li>进程信息 → <code>/proc/1234/</code></li><li>系统配置 → <code>/etc/nginx/nginx.conf</code></li></ul><p>这意味着你可以用统一的方式（读/写文件）来操作几乎所有系统资源。</p><h3 id="_2-小工具组合完成复杂任务" tabindex="-1">2. 小工具组合完成复杂任务 <a class="header-anchor" href="#_2-小工具组合完成复杂任务" aria-label="Permalink to &quot;2. 小工具组合完成复杂任务&quot;">​</a></h3><p>Linux 提供大量只做一件事的小工具，通过**管道（<code>|</code>）**组合：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 找出占用内存最多的5个进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 统计某个 IP 访问 nginx 的次数</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/nginx/access.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;192.168.1.100&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre></div><h3 id="_3-配置即文本文件" tabindex="-1">3. 配置即文本文件 <a class="header-anchor" href="#_3-配置即文本文件" aria-label="Permalink to &quot;3. 配置即文本文件&quot;">​</a></h3><p>几乎所有软件的配置都是纯文本，存放在 <code>/etc/</code> 下。这意味着：</p><ul><li>配置可以版本控制（git）</li><li>配置可以脚本化</li><li>出了问题直接看文件就能排查</li></ul><hr><h2 id="linux-vs-windows-vs-macos" tabindex="-1">Linux vs Windows vs macOS <a class="header-anchor" href="#linux-vs-windows-vs-macos" aria-label="Permalink to &quot;Linux vs Windows vs macOS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>Linux</th><th>Windows</th><th>macOS</th></tr></thead><tbody><tr><td>核心优势</td><td>稳定、免费、可定制</td><td>生态丰富、易用</td><td>Unix 内核、开发友好</td></tr><tr><td>服务器份额</td><td>~96%</td><td>~3%</td><td>&lt;1%</td></tr><tr><td>图形界面</td><td>可选（桌面版有）</td><td>强制</td><td>强制</td></tr><tr><td>文件系统</td><td>ext4、xfs、btrfs</td><td>NTFS</td><td>APFS</td></tr><tr><td>命令行</td><td>bash/zsh（原生强大）</td><td>PowerShell/CMD（较弱）</td><td>zsh（基于 BSD）</td></tr><tr><td>开源</td><td>是</td><td>否</td><td>部分</td></tr></tbody></table><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Linux 是一个内核，搭配 GNU 工具集组成完整操作系统</li><li>主流发行版分为 <strong>Debian 系</strong>（Ubuntu）和 <strong>RedHat 系</strong>（CentOS/Rocky）两大阵营</li><li>&quot;一切皆文件&quot;和&quot;管道组合&quot;是 Linux 的核心设计哲学</li><li>初学者推荐从 Ubuntu 22.04 LTS 开始</li></ul>`,30)]))}const k=s(d,[["render",e]]);export{u as __pageData,k as default};
